// "Vandaag en straks": a drag comparison per case. Both layers share one layout, so dragging the handle
// turns the AS-IS picture into the TO-BE picture in place. Text and numbers come from
// data/before-after.json (generated by scripts/build.mjs from the model and the BPMN files).
(() => {
  const root = document.getElementById("ba");
  if (!root) return;
  const tabs = document.getElementById("ba-tabs");
  const delta = document.getElementById("ba-delta");
  const range = root.querySelector(".ba-range");
  const before = root.querySelector(".ba-before");
  const after = root.querySelector(".ba-after");
  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;");

  const ICON = {
    manueel: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h9l3 3v15H6z" fill="none" stroke="currentColor" stroke-width="2"/><path d="M9 10h6M9 14h6M9 18h4" stroke="currentColor" stroke-width="2"/></svg>',
    mens: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4" fill="none" stroke="currentColor" stroke-width="2"/><path d="M4 21c1-4 4-6 8-6s7 2 8 6" fill="none" stroke="currentColor" stroke-width="2"/></svg>',
    wachten: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" stroke-width="2"/><path d="M12 7v5l3 3" fill="none" stroke="currentColor" stroke-width="2"/></svg>',
    automatisch: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13 2 4 14h7l-1 8 9-12h-7z" fill="currentColor"/></svg>',
  };

  let pos = 50;
  const set = (p) => {
    pos = Math.max(0, Math.min(100, p));
    root.style.setProperty("--pos", `${pos}%`);
    // near an edge the side labels would sit on top of the content: hide them, and keep the knob inside the frame
    root.classList.toggle("ba-edge", pos < 14 || pos > 86);
    const w = root.clientWidth, x = (pos / 100) * w, r = 30;
    root.style.setProperty("--knob-x", `${Math.max(0, r - x) - Math.max(0, x - (w - r))}px`);
    range.value = String(Math.round(pos));
    range.setAttribute("aria-valuetext", pos > 60 ? "vooral vandaag" : pos < 40 ? "vooral straks" : "half vandaag, half straks");
  };

  function layer(s, kind, kpis) {
    const isAfter = kind === "after";
    return `<div class="ba-inner">
      <div class="ba-top"><span class="ba-tag">${isAfter ? "Straks · TO-BE" : "Vandaag · AS-IS"}</span>
        <span class="ba-meta"><b>${s.steps.length}</b> stappen · <b>${s.counts.manual}</b> door mensen · <b>${s.counts.auto}</b> automatisch · <b>${s.lanes}</b> rollen</span></div>
      <p class="ba-head">${esc(s.headline)}</p>
      <ol class="ba-steps">${s.steps.map((st) => `<li class="k-${st.kind}" title="${esc(st.kind)}">${ICON[st.kind]}<span>${esc(st.name)}</span></li>`).join("")}<li class="ba-end"><span>${esc(s.end)}</span></li></ol>
      <div class="ba-kpis">${kpis.map((k) => `<div class="ba-kpi"><span>${esc(k.label)}</span><b>${esc(isAfter ? k.tobe : k.asis)}</b></div>`).join("")}</div>
      <ul class="ba-list">${s.list.map((x) => `<li>${esc(x)}</li>`).join("")}</ul>
    </div>`;
  }

  function show(c) {
    before.innerHTML = layer(c.asis, "before", c.kpis);
    after.innerHTML = layer(c.tobe, "after", c.kpis);
    delta.innerHTML = `<table><caption class="sr-only">Vandaag en straks, ${esc(c.tab)}</caption>
      <thead><tr><th scope="col">Wat</th><th scope="col">Vandaag</th><th scope="col" aria-hidden="true"></th><th scope="col">Straks</th><th scope="col">Bron</th></tr></thead>
      <tbody>${c.kpis.map((k) => `<tr><th scope="row">${esc(k.label)}</th><td class="was">${esc(k.asis)}</td><td class="arrow" aria-hidden="true">→</td><td class="now">${esc(k.tobe)}</td><td class="note">${esc(k.note ?? "")}</td></tr>`).join("")}</tbody></table>`;
    root.dataset.case = c.id;
    align();
  }

  // same block, same height in both layers, so the two pictures line up under the handle
  const BLOCKS = [".ba-top", ".ba-head", ".ba-steps", ".ba-kpis", ".ba-list"];
  function align() {
    for (const sel of BLOCKS) {
      const a = before.querySelector(sel), b = after.querySelector(sel);
      if (!a || !b) continue;
      a.style.minHeight = b.style.minHeight = "";
      const h = Math.max(a.offsetHeight, b.offsetHeight);
      a.style.minHeight = b.style.minHeight = `${h}px`;
    }
  }
  addEventListener("resize", () => requestAnimationFrame(align));
  document.fonts?.ready.then(align);

  // dragging anywhere on the stage; vertical swipes still scroll the page (touch-action: pan-y)
  let dragging = false;
  const toPos = (e) => { const r = root.getBoundingClientRect(); return ((e.clientX - r.left) / r.width) * 100; };
  root.addEventListener("pointerdown", (e) => { if (e.button !== 0) return; e.preventDefault(); dragging = true; root.setPointerCapture(e.pointerId); root.classList.add("dragging"); stop(); set(toPos(e)); });
  root.addEventListener("pointermove", (e) => { if (dragging) set(toPos(e)); });
  const end = () => { dragging = false; root.classList.remove("dragging"); };
  root.addEventListener("pointerup", end);
  root.addEventListener("pointercancel", end);
  range.addEventListener("input", () => { stop(); set(Number(range.value)); });

  // "speel af": sweep from today to tomorrow
  let raf = 0;
  const stop = () => cancelAnimationFrame(raf);
  function animate(points, ms) {
    stop();
    if (reduced) { set(points.at(-1)); return; }
    const t0 = performance.now();
    const seg = ms / (points.length - 1);
    const ease = (t) => (t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2);
    const step = (now) => {
      const t = Math.min((now - t0) / seg, points.length - 1);
      const i = Math.min(Math.floor(t), points.length - 2);
      set(points[i] + (points[i + 1] - points[i]) * ease(t - i));
      if (t < points.length - 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
  }
  document.querySelectorAll("[data-ba-pos]").forEach((b) => b.addEventListener("click", () => animate([pos, Number(b.dataset.baPos)], 700)));
  document.querySelector("[data-ba-play]")?.addEventListener("click", () => animate([pos, 100, 0], 3200));

  fetch("data/before-after.json").then((r) => r.json()).then(({ cases }) => {
    tabs.innerHTML = cases.map((c, i) => `<button class="btn small${i ? " ghost" : ""}" role="tab" aria-selected="${!i}" data-ba-case="${c.id}">${esc(c.tab)}</button>`).join("");
    tabs.querySelectorAll("button").forEach((b) => b.addEventListener("click", () => {
      tabs.querySelectorAll("button").forEach((x) => { x.classList.add("ghost"); x.setAttribute("aria-selected", "false"); });
      b.classList.remove("ghost"); b.setAttribute("aria-selected", "true");
      show(cases.find((c) => c.id === b.dataset.baCase));
      animate([pos, 85, 50], 900);
    }));
    show(cases[0]);
    set(50);
    if (location.hash === "#voor-na") document.getElementById("voor-na").scrollIntoView();
    // a small hint the first time the comparison scrolls into view
    new IntersectionObserver((entries, obs) => {
      if (entries.some((e) => e.isIntersecting)) { obs.disconnect(); animate([50, 82, 18, 50], 2600); }
    }, { threshold: 0.4 }).observe(root);
  }).catch(() => { before.innerHTML = '<div class="ba-inner"><p class="ba-head">De vergelijking kon niet laden. Zie de cases op GitHub.</p></div>'; });
})();
